import { describe, expect, it } from 'vitest';

import { evaluateBudget } from '../ContextBudget';

describe('evaluateBudget', () => {
  it('estimates one token for every four bytes', () => {
    expect(evaluateBudget(400, 100)).toEqual({
      bytes: 400,
      estimatedTokens: 100,
      limit: 100,
      marginReserve: 0,
      withinLimit: true,
    });
  });

  it('marks values above the limit as over budget', () => {
    expect(evaluateBudget(404, 100).withinLimit).toBe(false);
  });

  it('respects margin reserve when checking budget', () => {
    expect(evaluateBudget(400, 100, 20)).toEqual({
      bytes: 400,
      estimatedTokens: 100,
      limit: 100,
      marginReserve: 20,
      withinLimit: false,
    });
  });

  it('allows content within budget minus margin reserve', () => {
    expect(evaluateBudget(320, 100, 20)).toEqual({
      bytes: 320,
      estimatedTokens: 80,
      limit: 100,
      marginReserve: 20,
      withinLimit: true,
    });
  });

  it('treats zero margin reserve as no reserve', () => {
    expect(evaluateBudget(400, 100, 0)).toEqual({
      bytes: 400,
      estimatedTokens: 100,
      limit: 100,
      marginReserve: 0,
      withinLimit: true,
    });
  });

  it('marks content at exactly available budget boundary as within limit', () => {
    expect(evaluateBudget(320, 100, 20).withinLimit).toBe(true);
  });
});

